from abc import abstractmethod, ABCMeta
from six import add_metaclass


class Device(object):
    _vendor = None
    _model = None
    _version = None

    @classmethod
    def get_vendor(cls):
        return cls._vendor

    @classmethod
    def get_model(cls):
        return cls._model

    @classmethod
    def get_version(cls):
        return cls._version

    @classmethod
    def is_vendor_matched(cls, vendor):
        if not vendor and not cls._vendor:
            return True
        return str(vendor).lower() == str(cls._vendor).lower()

    @classmethod
    def is_model_matched(cls, model):
        if not model and not cls._model:
            return True
        return str(model).lower() == str(cls._model).lower()

    @classmethod
    def is_version_matched(cls, version):
        if not version and not cls._version:
            return True
        return str(version).lower() == str(cls._version).lower()


@add_metaclass(ABCMeta)
class AvailableDevices(object):

    def find_devices(self, **kwargs):
        vendor = kwargs.setdefault('vendor')
        model = kwargs.setdefault('model')
        version = kwargs.setdefault('version')
        device_classes = self._get_available_devices()
        target_devices = []
        for device_class in device_classes:
            if vendor and (not device_class.is_vendor_matched(vendor)):
                continue

            if model and (not device_class.is_model_matched(model)):
                continue

            if version and (not device_class.is_version_matched(version)):
                continue

            target_devices.append(device_class)

        return target_devices

    def find_default_device(self, **kwargs):
        pass

    @abstractmethod
    def _get_available_devices(self):
        raise NotImplementedError
